import os, urllib.request, urllib.parse, http.cookiejar
base=os.environ['LAB30_URL'].rstrip('/')
cj=http.cookiejar.CookieJar(); op=urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))
data=urllib.parse.urlencode({'username':os.environ['LAB30_USER'],'password':os.environ['LAB30_PASSWORD']}).encode()
try:
    op.open(urllib.request.Request(base+'/auth/login.php', data=data), timeout=10)
except Exception as e:
    print('login attempt',e)
for q in ['http://fixtures:8080/templates/season.php','http://fixtures:8080/catalog-info']:
    u=base+'/ops/template-preview.php?'+urllib.parse.urlencode({'template':q})
    try:
        r=op.open(u, timeout=10); b=r.read().decode('utf-8','replace')
        print('INPUT',q,'STATUS',r.status); print(b[:300])
    except Exception as e:
        print('INPUT',q,'ERR',e)
